}

function coverageStoreBounds(store: TiledCoverageStore): Bounds | null {
  if (store.defaultCoverage !== 0) {
    return { left: 0, top: 0, right: store.width - 1, bottom: store.height - 1 };
  }
  let minX = store.width;
