  const right = Math.min(layerWidth - 1, Math.ceil(maxX) + 1);
  const bottom = Math.min(layerHeight - 1, Math.ceil(maxY) + 1);
  if (right < left || bottom < top) return null;
  return { left, top, right, bottom };
