  const layer: TextLayer = {
    kind: 'text',
    id: options.id,
    name: options.name,
    text: options.text ?? 'Text',
    width: options.width,
    height: options.height,
    style: copyTextStyle(style),
    ...layerBase(options),
    rasterMask: copyRasterMask(options.rasterMask),
    vectorMask: copyVectorMask(options.vectorMask),
