import { TiledCoverageStore, TiledPixelStore } from '@freetoshop/pixel-storage';

export type LayerId = string;

export interface LayerTransform {
  readonly a: number;
  readonly b: number;
  readonly c: number;
  readonly d: number;
  readonly e: number;
  readonly f: number;
}

export interface TransformPoint {
  readonly x: number;
  readonly y: number;
}

export const BLEND_MODES = [
  'normal',
  'multiply',
  'screen',
  'overlay',
