      assertFinite(adjustment.saturation, 'Adjustment saturation');
      assertFinite(adjustment.lightness, 'Adjustment lightness');
      if (
        adjustment.hue < -180 ||
        adjustment.hue > 180 ||
        adjustment.saturation < -100 ||
        adjustment.saturation > 100 ||
        adjustment.lightness < -100 ||
