import type { CSSProperties, ReactNode } from 'react';
export function EditorShell({
  children,
  rightDockWidth,
}: {
  readonly children: ReactNode;
  readonly rightDockWidth: number;
}) {
  return (
    <div
      className="app-shell"
      style={{ '--right-dock-width': `${String(rightDockWidth)}px` } as CSSProperties}
    >
      {children}
    </div>
  );
}

import { useCallback, useEffect, useRef, useState, type KeyboardEvent } from 'react';
import type { Tool } from '../editor/types.js';
import { Icon } from '../ui/Icon.js';
import { TOOL_FAMILIES, type ToolDefinition } from '../tools/toolRegistry.js';

export interface ToolRailProps {
  readonly documentOpen: boolean;
  readonly transformAvailable: boolean;
  readonly tool: Tool;
  readonly onSelectTool: (tool: Tool) => void;
  readonly onActivateCrop: () => void;
  readonly onTogglePanels: () => void;
  readonly foregroundColor: string;
  readonly backgroundColor: string;
  readonly onForegroundColorChange: (color: string) => void;
  readonly onBackgroundColorChange: (color: string) => void;
}

export function ToolRail(props: ToolRailProps) {
  const [openFamily, setOpenFamily] = useState<string | null>(null);
  const railRef = useRef<HTMLElement>(null);
  const triggerRefs = useRef(new Map<string, HTMLButtonElement>());
  const closeFamily = useCallback(
    (returnFocus: boolean) => {
      const family = openFamily;
      setOpenFamily(null);
      if (returnFocus && family)
        requestAnimationFrame(() => triggerRefs.current.get(family)?.focus());
    },
    [openFamily],
  );
  const openFamilyMenu = (family: string) => setOpenFamily(family);
  const focusFlyoutItem = (family: string, index: number) => {
    requestAnimationFrame(() => {
      const items = railRef.current?.querySelectorAll<HTMLButtonElement>(
        `[data-family="${family}"] [role="menuitem"]`,
      );
      items?.[index]?.focus();
    });
  };
  const handleFlyoutKeyDown = (event: KeyboardEvent<HTMLDivElement>, family: string) => {
    const items = [
      ...event.currentTarget.querySelectorAll<HTMLButtonElement>('button:not(:disabled)'),
    ];
    const index = items.indexOf(document.activeElement as HTMLButtonElement);
    const delta = event.key === 'ArrowDown' || event.key === 'ArrowRight' ? 1 : -1;
    if (
      event.key === 'ArrowDown' ||
      event.key === 'ArrowRight' ||
      event.key === 'ArrowUp' ||
      event.key === 'ArrowLeft'
    ) {
      event.preventDefault();
      focusFlyoutItem(family, (index + delta + items.length) % items.length);
    } else if (event.key === 'Home' || event.key === 'End') {
      event.preventDefault();
      focusFlyoutItem(family, event.key === 'Home' ? 0 : items.length - 1);
    } else if (event.key === 'Escape') {
      event.preventDefault();
      closeFamily(true);
    } else if (event.key === 'Enter' || event.key === ' ') {
      event.preventDefault();
      items[index]?.click();
      closeFamily(true);
    } else if (event.key === 'Tab') closeFamily(false);
  };
  useEffect(() => {
    if (openFamily === null) return;
    const onPointerDown = (event: PointerEvent) => {
      if (!railRef.current?.contains(event.target as Node)) closeFamily(false);
    };
    const onEscape = (event: globalThis.KeyboardEvent) => {
      if (event.key === 'Escape') closeFamily(true);
    };
    window.addEventListener('pointerdown', onPointerDown);
    window.addEventListener('keydown', onEscape);
    return () => {
      window.removeEventListener('pointerdown', onPointerDown);
      window.removeEventListener('keydown', onEscape);
    };
  }, [closeFamily, openFamily]);
  return (
    <aside ref={railRef} className="tool-rail" aria-label="Canvas tools">
      {TOOL_FAMILIES.map(({ family, tools }) => {
        const active = tools.find((item) => item.tool === props.tool) ?? tools[0];
        if (!active) return null;
        return (
          <div className="tool-family" data-family={family} key={family}>
            <ToolButton
              item={active}
              {...props}
              onOpenFamily={
                tools.length > 1
                  ? () =>
                      openFamily === family
                        ? closeFamily(false)
                        : (openFamilyMenu(family),
                          focusFlyoutItem(
                            family,
                            Math.max(
                              0,
                              tools.findIndex((item) => item.tool === props.tool),
                            ),
                          ))
                  : undefined
              }
              buttonRef={(element) => {
                if (element) triggerRefs.current.set(family, element);
                else triggerRefs.current.delete(family);
              }}
              hasPopup={tools.length > 1}
              expanded={openFamily === family}
              onKeyDown={(event) => {
                if (tools.length > 1 && ['ArrowRight', 'ArrowDown', 'F4'].includes(event.key)) {
                  event.preventDefault();
                  openFamilyMenu(family);
                  focusFlyoutItem(
                    family,
                    Math.max(
                      0,
                      tools.findIndex((item) => item.tool === props.tool),
                    ),
                  );
                }
              }}
            />
            {tools.length > 1 && <span className="tool-family-indicator" aria-hidden="true" />}
            {openFamily === family && (
              <div
                className="tool-flyout"
                role="menu"
                aria-label={`${family} tools`}
                onKeyDown={(event) => handleFlyoutKeyDown(event, family)}
              >
                {tools.map((item) => (
                  <ToolButton
                    key={item.tool}
                    item={item}
                    {...props}
                    menuItem
                    onOpenFamily={() => closeFamily(false)}
                  />
                ))}
              </div>
            )}
          </div>
        );
      })}
      <div className="rail-spacer" />
      <div className="rail-colors" title="Foreground and background colors">
        <input
          aria-label="Foreground color"
          type="color"
          value={props.foregroundColor}
          onChange={(event) => props.onForegroundColorChange(event.target.value)}
        />
        <input
          className="background-swatch"
          aria-label="Background color"
          type="color"
          value={props.backgroundColor}
          onChange={(event) => props.onBackgroundColorChange(event.target.value)}
        />
      </div>
      <button
        className="rail-color-command rail-default-colors"
        title="Default colors (D)"
        aria-label="Default foreground and background colors"
        onClick={() => {
          props.onForegroundColorChange('#000000');
          props.onBackgroundColorChange('#ffffff');
        }}
      >
        D
      </button>
      <button
        className="rail-color-command rail-swap-colors"
        title="Swap colors (X)"
        aria-label="Swap foreground and background colors"
        onClick={() => {
          props.onForegroundColorChange(props.backgroundColor);
          props.onBackgroundColorChange(props.foregroundColor);
        }}
      >
        <Icon name="swap" />
      </button>
      <button className="tool-button" aria-label="Toggle panels" onClick={props.onTogglePanels}>
        <Icon name="panels" />
      </button>
    </aside>
  );
}

function ToolButton({
  item,
  documentOpen,
  transformAvailable,
  tool,
  onSelectTool,
  onActivateCrop,
  onOpenFamily,
  buttonRef,
  onKeyDown,
  expanded,
  hasPopup,
  menuItem = false,
}: ToolRailProps & {
  readonly item: ToolDefinition;
  readonly onOpenFamily?: () => void;
  readonly buttonRef?: (element: HTMLButtonElement | null) => void;
  readonly onKeyDown?: (event: KeyboardEvent<HTMLButtonElement>) => void;
  readonly expanded?: boolean;
  readonly hasPopup?: boolean;
  readonly menuItem?: boolean;
}) {
  const disabled =
    item.tool === 'transform' ? !transformAvailable : item.needsDocument && !documentOpen;
  const activate = () => {
    if (item.tool === 'crop') onActivateCrop();
    else onSelectTool(item.tool);
    onOpenFamily?.();
  };
  return (
    <button
      className="tool-button"
      role={menuItem ? 'menuitem' : undefined}
      ref={buttonRef}
      onKeyDown={onKeyDown}
      aria-haspopup={hasPopup ? 'menu' : undefined}
      aria-expanded={hasPopup ? expanded : undefined}
      aria-label={item.accessibleLabel}
      title={`${item.label} (${item.shortcut})`}
      disabled={disabled}
      aria-pressed={!menuItem ? tool === item.tool : undefined}
      onClick={activate}
      onContextMenu={(event) => {
        if (onOpenFamily) {
          event.preventDefault();
          onOpenFamily();
        }
      }}
    >
      <Icon name={item.icon} />
      <span className="tool-label">{item.label.replace(' Tool', '')}</span>
    </button>
  );
}

import type { SelectionCombineMode } from '@freetoshop/core-document';
import type { DocumentRectangle, EditTarget, Tool } from '../editor/types.js';
import { toolDefinition } from '../tools/toolRegistry.js';

type Refinement = 'feather' | 'expand' | 'contract' | 'smooth' | 'border';

export interface ToolOptionsBarProps {
  readonly tool: Tool;
  readonly status: string;
  readonly documentOpen: boolean;
  readonly selectionActive: boolean;
  readonly brushSize: number;
  readonly brushOpacity: number;
  readonly brushColor: string;
  readonly editTarget: EditTarget;
  readonly selectionMode: SelectionCombineMode;
  readonly selectionRadius: number;
  readonly wandTolerance: number;
  readonly wandContiguous: boolean;
  readonly cropRectangle: DocumentRectangle | null;
  readonly pathAnchorCount: number;
  readonly zoom: number;
  readonly busy: boolean;
  readonly operationProgress: number | null;
  readonly onFit: () => void;
  readonly onActualSize: () => void;
  readonly onBrushSizeChange: (value: number) => void;
  readonly onBrushOpacityChange: (value: number) => void;
  readonly onBrushColorChange: (value: string) => void;
  readonly onSelectionModeChange: (value: SelectionCombineMode) => void;
  readonly onDeselect: () => void;
  readonly onWandToleranceChange: (value: number) => void;
  readonly onWandContiguousChange: (value: boolean) => void;
  readonly onSelectionRadiusChange: (value: number) => void;
  readonly onRefineSelection: (operation: Refinement) => void;
  readonly onCropRectangleChange: (rectangle: DocumentRectangle) => void;
  readonly onApplyCrop: () => void;
  readonly onCancelCrop: () => void;
  readonly onFinishPath: (closed: boolean) => void;
  readonly onCancelPath: () => void;
  readonly onZoomChange: (zoom: number) => void;
  readonly onCancelOperation: () => void;
}

export function ToolOptionsBar(props: ToolOptionsBarProps) {
  const selectionTool =
    props.tool === 'select' ||
    props.tool === 'ellipse' ||
    props.tool === 'lasso' ||
    props.tool === 'wand';
  return (
    <div className="options-bar" aria-label="Tool options">
      <span className="options-label">{toolDefinition(props.tool).label}</span>
      <span id="edit-target-status" className="target-status" aria-live="polite">
        {props.status}
      </span>
      <div className="option-group">
        <button className="action-button" disabled={!props.documentOpen} onClick={props.onFit}>
          Fit
        </button>
        <button
          className="action-button"
          disabled={!props.documentOpen}
          onClick={props.onActualSize}
        >
          100%
        </button>
      </div>
      {(props.tool === 'brush' || props.tool === 'eraser') && (
        <>
          <div className="option-group">
            <label htmlFor="brush-size">Size</label>
            <input
              id="brush-size"
              aria-label="Brush size"
              type="range"
              min="1"
              max="200"
              value={props.brushSize}
              onChange={(event) => props.onBrushSizeChange(Number(event.target.value))}
            />
            <span>{props.brushSize}px</span>
          </div>
          <div className="option-group">
            <label htmlFor="brush-opacity">Opacity</label>
            <input
              id="brush-opacity"
              aria-label="Brush opacity"
              type="range"
              min="1"
              max="100"
              value={props.brushOpacity}
              onChange={(event) => props.onBrushOpacityChange(Number(event.target.value))}
            />
            <span>{props.brushOpacity}%</span>
          </div>
          {props.tool === 'brush' && props.editTarget === 'pixels' && (
            <label className="color-option">
              Color
              <input
                aria-label="Brush color"
                type="color"
                value={props.brushColor}
                onChange={(event) => props.onBrushColorChange(event.target.value)}
              />
            </label>
          )}
        </>
      )}
      {selectionTool && (
        <>
          <div className="option-group">
            <label htmlFor="selection-mode">Selection mode</label>
            <select
              id="selection-mode"
              aria-label="Selection mode"
              value={props.selectionMode}
              onChange={(event) =>
                props.onSelectionModeChange(event.target.value as SelectionCombineMode)
              }
            >
              <option value="replace">Replace</option>
              <option value="add">Add</option>
              <option value="subtract">Subtract</option>
              <option value="intersect">Intersect</option>
            </select>
            {props.selectionActive && (
              <button className="action-button" onClick={props.onDeselect}>
                Deselect
              </button>
            )}
          </div>
          {props.tool === 'wand' && (
            <div className="option-group">
              <label htmlFor="wand-tolerance">Tolerance</label>
              <input
                id="wand-tolerance"
                aria-label="Magic Wand tolerance"
                type="range"
                min="0"
                max="255"
                value={props.wandTolerance}
                onChange={(event) => props.onWandToleranceChange(Number(event.target.value))}
              />
              <span>{props.wandTolerance}</span>
              <label className="inline-check">
                <input
                  type="checkbox"
                  checked={props.wandContiguous}
                  onChange={(event) => props.onWandContiguousChange(event.target.checked)}
                />
                Contiguous
              </label>
            </div>
          )}
          {props.selectionActive && (
            <div className="option-group selection-refine" aria-label="Refine selection">
              <label htmlFor="selection-radius">Radius</label>
              <input
                id="selection-radius"
                aria-label="Selection refinement radius"
                type="number"
                min="0"
                max="100"
                step="1"
                value={props.selectionRadius}
                onChange={(event) =>
                  props.onSelectionRadiusChange(
                    Math.max(0, Math.min(100, Number(event.target.value))),
                  )
                }
              />
              {(['feather', 'expand', 'contract', 'smooth', 'border'] as const).map((operation) => (
                <button
                  className="action-button"
                  key={operation}
                  onClick={() => props.onRefineSelection(operation)}
                >
                  {operation[0]?.toUpperCase()}
                  {operation.slice(1)}
                </button>
              ))}
            </div>
          )}
        </>
      )}
      {props.tool === 'crop' && (
        <div className="option-group crop-options" aria-label="Crop options">
          {(['x', 'y', 'width', 'height'] as const).map((key) => (
            <label key={key}>
              {key === 'x' ? 'X' : key === 'y' ? 'Y' : key === 'width' ? 'W' : 'H'}
              <input
                type="number"
                step="1"
                min={key === 'width' || key === 'height' ? 1 : undefined}
                aria-label={`Crop ${key}`}
                value={props.cropRectangle?.[key] ?? ''}
                disabled={!props.cropRectangle}
                onChange={(event) => {
                  if (!props.cropRectangle) return;
                  const value = Math.round(Number(event.target.value));
                  if (!Number.isFinite(value)) return;
                  props.onCropRectangleChange({
                    ...props.cropRectangle,
                    [key]: key === 'width' || key === 'height' ? Math.max(1, value) : value,
                  });
                }}
                onKeyDown={(event) => {
                  if (event.key === 'Enter') {
                    event.preventDefault();
                    props.onApplyCrop();
                  } else if (event.key === 'Escape') {
                    event.preventDefault();
                    props.onCancelCrop();
                  }
                }}
              />
            </label>
          ))}
          <button
            className="action-button primary"
            disabled={!props.cropRectangle}
            onClick={props.onApplyCrop}
          >
            Apply crop
          </button>
          <button
            className="action-button"
            disabled={!props.cropRectangle}
            onClick={props.onCancelCrop}
          >
            Cancel crop
          </button>
        </div>
      )}
      {props.tool === 'transform' && (
        <span className="transform-instructions" role="status">
          Drag square handles to scale and the round handle to rotate. Hold Shift for uniform
          scaling; Escape cancels the active gesture.
        </span>
      )}
      {props.tool === 'pen' && (
        <div className="option-group" aria-label="Pen options">
          <span>{props.pathAnchorCount} anchors</span>
          <button
            className="action-button primary"
            disabled={props.pathAnchorCount < 2}
            onClick={() => props.onFinishPath(false)}
          >
            Finish open path
          </button>
          <button
            className="action-button"
            disabled={props.pathAnchorCount < 3}
            onClick={() => props.onFinishPath(true)}
          >
            Close path
          </button>
          <button
            className="action-button"
            disabled={props.pathAnchorCount === 0}
            onClick={props.onCancelPath}
          >
            Cancel path
          </button>
        </div>
      )}
      <div className="option-group">
        <label className="sr-only" htmlFor="zoom">
          Canvas zoom
        </label>
        <input
          id="zoom"
          className="zoom-input"
          type="range"
          min="5"
          max="400"
          value={Math.round(props.zoom * 100)}
          disabled={!props.documentOpen}
          onChange={(event) => props.onZoomChange(Number(event.target.value) / 100)}
        />
        <span>{Math.round(props.zoom * 100)}%</span>
      </div>
      {props.busy && (
        <span role="status">
          Working locally…
          {props.operationProgress === null
            ? ''
            : ` ${String(Math.round(props.operationProgress * 100))}%`}
        </span>
      )}
      {props.operationProgress !== null && (
        <button className="action-button" type="button" onClick={props.onCancelOperation}>
          Cancel operation
        </button>
      )}
    </div>
  );
}

