          {props.operationProgress === null
            ? ''
            : ` ${String(Math.round(props.operationProgress * 100))}%`}
        </span>
      )}
      {props.operationProgress !== null && (
        <button className="action-button" type="button" onClick={props.onCancelOperation}>
          Cancel operation
        </button>
      )}
    </div>
  );
}

