function ToolButton({
  item,
  documentOpen,
  transformAvailable,
  tool,
  onSelectTool,
  onActivateCrop,
  onOpenFamily,
  buttonRef,
  onKeyDown,
  expanded,
  hasPopup,
  menuItem = false,
}: ToolRailProps & {
  readonly item: ToolDefinition;
  readonly onOpenFamily?: () => void;
  readonly buttonRef?: (element: HTMLButtonElement | null) => void;
  readonly onKeyDown?: (event: KeyboardEvent<HTMLButtonElement>) => void;
  readonly expanded?: boolean;
  readonly hasPopup?: boolean;
  readonly menuItem?: boolean;
}) {
  const disabled =
    item.tool === 'transform' ? !transformAvailable : item.needsDocument && !documentOpen;
  const activate = () => {
    if (item.tool === 'crop') onActivateCrop();
    else onSelectTool(item.tool);
    onOpenFamily?.();
  };
  return (
    <button
      className="tool-button"
      role={menuItem ? 'menuitem' : undefined}
      ref={buttonRef}
      onKeyDown={onKeyDown}
      aria-haspopup={hasPopup ? 'menu' : undefined}
      aria-expanded={hasPopup ? expanded : undefined}
      aria-label={item.accessibleLabel}
      title={`${item.label} (${item.shortcut})`}
      disabled={disabled}
      aria-pressed={!menuItem ? tool === item.tool : undefined}
      onClick={activate}
      onContextMenu={(event) => {
        if (onOpenFamily) {
          event.preventDefault();
          onOpenFamily();
        }
      }}
    >
      <Icon name={item.icon} />
      <span className="tool-label">{item.label.replace(' Tool', '')}</span>
    </button>
  );
}

