  const openImageSize = useCallback(
    (trigger?: HTMLButtonElement) => {
      if (!document) return;
      sizeDialogTriggerRef.current =
        trigger ?? window.document.querySelector<HTMLButtonElement>('[data-command="image-size"]');
      setImageSizeDraft({
