  });
  const [filterDraft, setFilterDraft] = useState<FilterDraft>({
    kind: 'contrast',
    contrast: 20,
    inputBlack: 0,
    gamma: 1,
    inputWhite: 255,
    outputBlack: 0,
    outputWhite: 255,
