import { createSelectionMask, createDocument } from '@freetoshop/core-document';
import { TiledCoverageStore } from '@freetoshop/pixel-storage';
import { describe, expect, it, vi } from 'vitest';
import {
  movePathHandle,
  parseSizeDraft,
  parseTransformDraft,
  selectionBounds,
  selectionRectangle,
} from './model.js';

describe('editor model helpers', () => {
  it('normalizes selection rectangles and finds nonzero mask bounds', () => {
    expect(selectionRectangle({ x: 8.8, y: 5.2 }, { x: 2.1, y: 9.01 })).toEqual({
      x: 2,
      y: 5,
      width: 7,
      height: 5,
    });
    const document = createDocument({
      id: 'selection',
      name: 'Selection',
      width: 4,
      height: 3,
      selection: createSelectionMask({
        width: 4,
        height: 3,
        coverage: new Uint8ClampedArray([0, 0, 0, 0, 0, 64, 255, 0, 0, 255, 0, 0]),
      }),
    });
    expect(selectionBounds(document)).toEqual({ x: 1, y: 1, width: 2, height: 2 });
  });

  it('reports sparse complement selections as full-canvas without enumerating implicit tiles', () => {
    const store = TiledCoverageStore.uniform(4096, 4096, 255, 256).write({
      x: 1024,
      y: 2048,
      width: 1,
      height: 1,
      coverage: new Uint8ClampedArray([0]),
    }).store;
    const chunks = vi.spyOn(store, 'coverageChunks');
    const document = createDocument({
      id: 'complement-bounds',
      name: 'Complement bounds',
      width: 4096,
      height: 4096,
      selection: createSelectionMask({ width: 4096, height: 4096, coverageStore: store }),
    });
    expect(selectionBounds(document)).toEqual({ x: 0, y: 0, width: 4096, height: 4096 });
    expect(chunks).not.toHaveBeenCalled();
  });

  it('moves path anchors with their adjacent cubic controls without mutating the source', () => {
    const geometry = {
      type: 'path' as const,
      width: 20,
      height: 20,
      cornerRadius: 0,
      commands: [
        { type: 'move' as const, x: 2, y: 3 },
        {
          type: 'cubic' as const,
          control1X: 4,
          control1Y: 5,
          control2X: 8,
          control2Y: 9,
          x: 10,
          y: 11,
        },
      ],
    };
    const moved = movePathHandle(geometry, 0, 'anchor', { x: 5, y: 7 });
    expect(moved.commands).toEqual([
      { type: 'move', x: 5, y: 7 },
      {
        type: 'cubic',
        control1X: 7,
        control1Y: 9,
        control2X: 8,
        control2Y: 9,
        x: 10,
        y: 11,
      },
    ]);
    expect(geometry.commands[0]).toEqual({ type: 'move', x: 2, y: 3 });
  });

  it('validates transform and bounded document-size drafts', () => {
    expect(parseTransformDraft({ a: '1', b: '0', c: '0', d: '1', e: '12.5', f: '-4' })).toEqual({
      a: 1,
      b: 0,
      c: 0,
      d: 1,
      e: 12.5,
      f: -4,
    });
    expect(parseTransformDraft({ a: '1', b: '2', c: '2', d: '4', e: '0', f: '0' })).toBeNull();
    expect(parseSizeDraft('1024', '768')).toEqual({ width: 1024, height: 768, error: null });
    expect(parseSizeDraft('0', '768').error).toContain('positive whole numbers');
    expect(parseSizeDraft('32769', '1').error).toContain('cannot exceed');
  });
});

  const applyImageSize = useCallback(async () => {
    if (!document || parsedImageSize.error || operationAbortRef.current) return;
    if (
      parsedImageSize.width === document.canvas.width &&
      parsedImageSize.height === document.canvas.height
    ) {
      closeSizeDialog();
      notify('Image size is unchanged.');
      return;
    }
    const controller = new AbortController();
    operationAbortRef.current = controller;
    setBusy(true);
    setOperationProgress(0);
    try {
      const result = await getDocumentWorkerClient().run(
        {
          kind: 'resize',
          document,
          width: parsedImageSize.width,
          height: parsedImageSize.height,
          method: imageSizeDraft.method,
        },
        { signal: controller.signal, onProgress: setOperationProgress },
      );
      if (result.kind !== 'resize')
        throw new Error('The resize worker returned an invalid result.');
      const next = runCommand({
        label: 'Resize image',
        execute(current) {
          if (current !== document) {
            throw new Error('The document changed while the image was resizing. Please try again.');
          }
          return result.document;
        },
      });
      if (!next) return;
      closeSizeDialog();
      window.requestAnimationFrame(() => fitTarget(next));
      notify(
        `Image resized to ${String(parsedImageSize.width)} × ${String(parsedImageSize.height)} pixels.`,
      );
    } catch (error) {
      if (isAbortError(error)) notify('Image resize cancelled.');
      else notify(error instanceof Error ? error.message : 'Image resize failed.', 'error');
    } finally {
      if (operationAbortRef.current === controller) operationAbortRef.current = null;
      setOperationProgress(null);
      setBusy(false);
    }
  }, [
    closeSizeDialog,
    document,
    fitTarget,
    getDocumentWorkerClient,
    imageSizeDraft.method,
    notify,
    parsedImageSize,
    runCommand,
  ]);

  const applyFilter = useCallback(
    async (requestedDraft: FilterDraft = filterDraft) => {
      if (!document || !selectedLayer || filterError || operationAbortRef.current) return;
      if (selectedLayer.kind === 'smart-object' && requestedDraft.kind === 'gaussian-blur') {
        const smartFilter = createSmartFilterFromDraft(
          'gaussian-blur',
          requestedDraft,
          makeId('smart-filter'),
        );
        runCommand(
          setSmartObjectFilters(selectedLayer.id, [...selectedLayer.smartFilters, smartFilter]),
        );
        setLastFilter({ kind: 'gaussian-blur', draft: requestedDraft });
        closeSizeDialog();
        notify('Gaussian Blur added as a smart filter.');
        return;
      }
      if (selectedLayer.kind !== 'pixel') return;
      const controller = new AbortController();
      operationAbortRef.current = controller;
      setBusy(true);
      setOperationProgress(0);
      try {
        const worldTransform =
          findLayerWorldTransform(document, selectedLayer.id) ?? selectedLayer.transform;
        const result = await getDocumentWorkerClient().run(
          {
            kind: 'filter',
            layer: selectedLayer,
            selection: document.selection,
            worldTransform,
            draft: requestedDraft,
          },
          { signal: controller.signal, onProgress: setOperationProgress },
        );
        if (result.kind !== 'filter')
          throw new Error('The filter worker returned an invalid result.');
        if (result.patches.length === 0) {
          closeSizeDialog();
          notify(`${FILTER_LABELS[requestedDraft.kind]} made no pixel changes.`);
          return;
        }
        let pixelStore = selectedLayer.pixelStore;
        for (const patch of result.patches) {
          pixelStore = pixelStore.write({
            ...patch,
            pixels: new Uint8ClampedArray(patch.pixels),
          }).store;
        }
        const command = replacePixelStore(
          selectedLayer.id,
          pixelStore,
          `Apply ${FILTER_LABELS[requestedDraft.kind]}`,
        );
        const next = runCommand({
          label: command.label,
          execute(current) {
            if (current !== document) {
              throw new Error(
                'The document changed while the filter was running. Please try again.',
              );
            }
            return command.execute(current);
          },
        });
        if (!next) return;
