      {props.tool === 'pen' && (
        <div className="option-group" aria-label="Pen options">
          <span>{props.pathAnchorCount} anchors</span>
          <button
            className="action-button primary"
            disabled={props.pathAnchorCount < 2}
            onClick={() => props.onFinishPath(false)}
