            Finish open path
          </button>
          <button
            className="action-button"
            disabled={props.pathAnchorCount < 3}
            onClick={() => props.onFinishPath(true)}
          >
            Close path
          </button>
          <button
            className="action-button"
            disabled={props.pathAnchorCount === 0}
            onClick={props.onCancelPath}
